import numpy as np

def priority(item, bins):
    if len(bins) == 0:
        return np.array([])

    # Prioritize bins with smaller remaining capacities to reduce fragmentation
    # Score is inversely proportional to remaining capacity with a small bias for diversity
    scores = 1.0 / (bins + 1) * (item + 1e-9)  # Small bias to avoid identical scores

    return scores

import numpy as np

class PriorityState:
    def __init__(self):
        self.time_counter = 0
        self.randomness_factor = 0.1
        self.smoothing = 1e-6

def priority(item: int, bins: np.ndarray, state: PriorityState = None) -> np.ndarray:
    if state is None:
        state = PriorityState()

    if len(bins) == 0:
        return np.array([])

    state.time_counter += 1
    verbose_randomness = state.randomness_factor * np.log1p(0.01 * state.time_counter)

    target_capacities = bins + state.smoothing
    min_distances = np.minimum(target_capacities, 2 * item) - state.smoothing

    load_proxies = np.exp(0.1 * (bins / np.sum(bins))) - 1

    noise = verbose_randomness * (np.random.rand(len(bins)) - 0.5) * load_proxies

    smoothed_load = load_proxies / np.sum(load_proxies)

    scores = (1 / (min_distances + 1e-9)) + verbose_randomness * (noise + smoothed_load)
    return scores

import numpy as np

class PriorityState:
    def __init__(self):
        self.time_counter = 0

def priority(item: int, bins: np.ndarray, state: PriorityState = None) -> np.ndarray:
    if state is None:
        state = PriorityState()

    if len(bins) == 0:
        return np.array([])

    state.time_counter += 1
    target_capacities = bins
    min_distances = np.minimum(target_capacities, 2 * item)

    scores = 1 / (min_distances + 1e-9)
    return scores
